#include <stdio.h>

void swap(int *a, int *b) {
    int temp = *a;   // сохранили значение по первому адресу
    *a = *b;         // положили туда значение второго
    *b = temp;       // а во второй - сохранённое первое
}

int main(void) {
    int x = 1, y = 2;
    swap(&x, &y);
    printf("%d %d\n", x, y);   // 2 1
    return 0;
}

