typedef struct {
    char name[20];
    int  score;
} Player;

int best(const Player *arr, int n) {
    int top = 0;                       // начинаем с первого, а не с нуля-счёта
    for (int i = 1; i < n; i++) {
        if (arr[i].score > arr[top].score) {
            top = i;
        }
    }
    return top;
}

int main(void) {
    Player team[3] = { {"Али", 30}, {"Вали", 70}, {"Гани", 50} };
    int i = best(team, 3);
    printf("%s %d\n", team[i].name, team[i].score);
    return 0;
}

